mapper.select:
SELECT DOCTYPE, REGISTER_USER, REGISTER_DATETIME
FROM HDOC_DOCUMENT_LIST
WHERE 1=1


         AND DOCTYPE != #{doctype}
         AND DOCTYPE > #{doctype}
         AND DOCTYPE < #{doctype}
         AND DOCTYPE = #{doctype}





         AND REGISTER_USER != #{registerUser}
         AND REGISTER_USER > #{registerUser}
         AND REGISTER_USER < #{registerUser}
         AND REGISTER_USER = #{registerUser}




         AND REGISTER_DATETIME != #{registerDatetime}
         AND REGISTER_DATETIME > #{registerDatetime}
         AND REGISTER_DATETIME < #{registerDatetime}
         AND REGISTER_DATETIME = #{registerDatetime}
